function pathParameter(name: string) {
  return {
    name,
    in: 'path',
    required: true,
    schema: { type: 'string' },
  } as const;
}

function queryParameter(
  name: string,
  schema: Record<string, unknown>,
) {
  return {
    name,
    in: 'query',
    required: false,
    schema,
  } as const;
}

function limitParameter(defaultValue: number, maxValue: number) {
  return queryParameter('limit', {
    type: 'integer',
    minimum: 1,
    maximum: maxValue,
    default: defaultValue,
  });
}

function jsonRequest(schemaName: string) {
  return {
    required: true,
    content: {
      'application/json': {
        schema: { $ref: `#/components/schemas/${schemaName}` },
      },
    },
  } as const;
}

function jsonResponse(
  description: string,
  schemaName: string,
  status = '200',
) {
  return {
    [status]: {
      description,
      content: {
        'application/json': {
          schema: { $ref: `#/components/schemas/${schemaName}` },
        },
      },
    },
  } as const;
}

function jsonNullableResponse(
  description: string,
  schemaName: string,
  status = '200',
) {
  return {
    [status]: {
      description,
      content: {
        'application/json': {
          schema: {
            oneOf: [{ $ref: `#/components/schemas/${schemaName}` }, { type: 'null' }],
          },
        },
      },
    },
  } as const;
}

function jsonArrayResponse(description: string, schemaName: string) {
  return {
    '200': {
      description,
      content: {
        'application/json': {
          schema: {
            type: 'array',
            items: { $ref: `#/components/schemas/${schemaName}` },
          },
        },
      },
    },
  } as const;
}
